arguments.command:
curl -s -X POST https://slack.com/api/users.list -d token=<TOKEN> -d limit=1000 | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR', d); sys.exit(1)
for u in d['members']:
    r=u.get('real_name') or u.get('profile',{}).get('real_name','')
    if 'omar' in r.lower() or 'haddad' in r.lower():
        print(u['id'], '|', r, '|', u.get('deleted'))
"

